PYTHONPATH=/app python - <<'PY'
import numpy as np
from forward import forward,A1,b1
seed=1;D=10
rng=np.random.default_rng(seed)
x0=rng.normal(scale=.3,size=D); d=rng.normal(size=D); d/=np.linalg.norm(d)
targets=np.sort(-(A1@x0+b1)/(A1@d))
print(targets)
R=1e6;tol=1e-9;npts=17
cache={}
def f(t):
    key=float(t)
    if key not in cache: cache[key]=forward(x0+key*d)
    return cache[key]
def check(a,b,target,depth=0):
    ts=np.linspace(a,b,npts);fs=np.array([f(t) for t in ts])
    A=np.column_stack([ts,np.ones_like(ts)]);coef=np.linalg.lstsq(A,fs,rcond=None)[0]
    err=np.max(np.abs(fs-A@coef));scale=max(1,np.max(np.abs(fs)))
    if err<=1e-13*scale:
        print('  linear stop depth',depth,'width',b-a,'err',err,'targets inside',[(t) for t in targets if a<=t<=b])
        return
    if b-a<=tol:
        print('  small stop',a,b,'contains',[t for t in targets if a<=t<=b]);return
    m=(a+b)/2
    if target<=m: check(a,m,target,depth+1)
    else: check(m,b,target,depth+1)
for target in targets:
 print('TARGET',target)
 check(-R,R,target)
